<template>
  <div class="demo-page category-picker-page">
    <header>
      <p class="demo-page__eyebrow">comps-vue3-picker</p>
      <h1 class="demo-page__title">Picker 组件</h1>
      <p class="demo-page__lead">
        两个互相独立的实现：CategoryPicker 对齐 HeyUI 分类选择器；RegionGroupPicker
        提供省、市、区县、乡镇的分组切换选择。
      </p>
    </header>

    <DemoPreview class="category-picker-preview">
      <section class="picker-example">
        <div class="picker-example__heading">
          <div>
            <p class="picker-example__eyebrow">HEYUI CATEGORY PICKER</p>
            <h2>分类选择器</h2>
          </div>
          <code>CategoryPicker</code>
        </div>
        <p class="picker-example__description">
          动态层级 tab、父级即时回显、叶子节点自动收起，并保留 HeyUI 的 key/object、
          单选多选、字段映射和异步数据 API。
        </p>
        <div class="picker-examples">
          <div class="picker-example__variant">
            <h3>选择器模式</h3>
            <LevaPlayground
              name="CategoryPickerSelector"
              :component="CategoryPicker"
              :schema="categorySelectorSchema"
              :presets="{ option: categoryOption, modelValue: 'west-lake', showChildCount: true }"
              :stage-style="pickerStageStyle"
            />
          </div>
          <div class="picker-example__variant">
            <h3>直接面板模式</h3>
            <LevaPlayground
              name="CategoryPickerPanel"
              :component="CategoryPicker"
              :schema="categoryPanelSchema"
              :presets="{ option: categoryOption, modelValue: 'west-lake', showChildCount: true, inline: true }"
              :stage-style="pickerStageStyle"
            />
          </div>
        </div>
      </section>

      <section class="picker-example">
        <div class="picker-example__heading">
          <div>
            <p class="picker-example__eyebrow">REGION GROUP PICKER</p>
            <h2>行政区划分组选择器</h2>
          </div>
          <code>RegionGroupPicker</code>
        </div>
        <p class="picker-example__description">
          固定省、市、区县、乡镇层级，逐级更新区域对象；该组件为独立实现，不依赖 CategoryPicker。
        </p>
        <div class="picker-examples">
          <div class="picker-example__variant">
            <h3>选择器模式</h3>
            <LevaPlayground
              name="RegionGroupPickerSelector"
              :component="RegionGroupPicker"
              :schema="regionSelectorSchema"
              :presets="{ option: regionOption, modelValue: regionValue }"
              :stage-style="pickerStageStyle"
            />
          </div>
          <div class="picker-example__variant">
            <h3>直接面板模式</h3>
            <LevaPlayground
              name="RegionGroupPickerPanel"
              :component="RegionGroupPicker"
              :schema="regionPanelSchema"
              :presets="{ option: regionOption, modelValue: regionValue, inline: true }"
              :stage-style="pickerStageStyle"
            />
          </div>
        </div>
      </section>

      <div class="picker-actions">
        <button type="button" class="demo-btn demo-btn--ghost" @click="reset">重置两个示例</button>
      </div>
    </DemoPreview>

    <p class="demo-note">
      开发环境直接引用工作区的 <code>comps-vue3-picker</code>，生产构建通过
      <code>preFetchLib('comps-vue3-picker')</code> 加载两个组件。
    </p>
  </div>
</template>

<script setup lang="ts">
import { defineAsyncComponent, ref } from 'vue'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { loadPickerLib } from '../configs/remote'
import areaRows from '../data/area_format_array.json'

const CategoryPicker = defineAsyncComponent({
  loader: async () => (await loadPickerLib()).CategoryPicker,
  timeout: 10000,
})
const RegionGroupPicker = defineAsyncComponent({
  loader: async () => (await loadPickerLib()).RegionGroupPicker,
  timeout: 10000,
})

const categoryOption = {
  datas: [
    {
      key: 'zhejiang',
      title: '浙江省',
      children: [
        { key: 'hangzhou', title: '杭州市', children: [{ key: 'west-lake', title: '西湖区' }, { key: 'yuhang', title: '余杭区' }] },
        { key: 'ningbo', title: '宁波市', children: [{ key: 'haishu', title: '海曙区' }] },
      ],
    },
    {
      key: 'jiangsu',
      title: '江苏省',
      children: [
        { key: 'nanjing', title: '南京市', children: [{ key: 'xuanwu', title: '玄武区' }] },
        { key: 'suzhou', title: '苏州市' },
      ],
    },
    { key: 'shanghai', title: '上海市', children: [{ key: 'pudong', title: '浦东新区' }] },
  ],
}

const regionOption = {
  datas: areaRows,
  dataMode: 'list' as const,
  keyName: 'i',
  titleName: 'n',
  parentName: 'p',
  childrenName: 'children',
}

const categoryValue = ref('west-lake')
const regionValue = ref<Record<string, number | undefined>>({ province: 35, city: 3501, area: 350104 })

const categoryControls = [
  { name: 'multiple', type: 'boolean', description: '是否允许多选', value: false },
  { name: 'disabled', type: 'boolean', description: '是否禁用', value: false },
  { name: 'placeholder', type: 'string', description: '未选择时的占位文案', value: '请选择分类' },
  { name: 'showAllLevels', type: 'boolean', description: '是否显示完整层级路径', value: true },
  { name: 'showChildCount', type: 'boolean', description: '是否显示子项数量', value: true },
]

const regionControls = [
  { name: 'disabled', type: 'boolean', description: '是否禁用', value: false },
  { name: 'placeholder', type: 'string', description: '选择器占位文案', value: '请选择行政区划' },
  { name: 'header', type: 'string', description: '面板标题', value: '行政区划' },
  { name: 'separator', type: 'string', description: '已选层级之间的分隔符', value: ' / ' },
]

const categorySelectorSchema = [{ name: 'inline', type: 'boolean', description: '显示模式', value: false }, ...categoryControls]
const categoryPanelSchema = [{ name: 'inline', type: 'boolean', description: '显示模式', value: true }, ...categoryControls]
const regionSelectorSchema = [{ name: 'inline', type: 'boolean', description: '显示模式', value: false }, ...regionControls]
const regionPanelSchema = [{ name: 'inline', type: 'boolean', description: '显示模式', value: true }, ...regionControls]
const pickerStageStyle = {
  minHeight: '360px',
  padding: '16px',
  boxSizing: 'border-box',
  alignItems: 'flex-start',
  justifyContent: 'flex-start',
}

function reset() {
  categoryValue.value = 'west-lake'
  regionValue.value = { province: 35, city: 3501, area: 350104 }
}
</script>

<style scoped>
.category-picker-preview { display: grid; gap: 22px; padding: 24px; }
.picker-example { padding: 24px; border: 1px solid var(--demo-border); border-radius: 16px; background: var(--demo-surface); }
.picker-examples { display: grid; grid-template-columns: 1fr; gap: 18px; }
.picker-example__variant { min-width: 0; padding: 16px; border: 1px solid var(--demo-border); border-radius: 12px; background: var(--demo-bg); }
.picker-example__variant h3 { margin: 0 0 10px; font-size: 15px; }
.picker-example__heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 8px; }
.picker-example__heading h2 { margin: 2px 0 0; font-size: 20px; }
.picker-example__heading code { flex: 0 0 auto; color: var(--demo-muted); }
.picker-example__eyebrow { margin: 0; color: var(--demo-accent); font-size: 11px; font-weight: 700; letter-spacing: .12em; }
.picker-example__description { max-width: 720px; margin: 0 0 20px; color: var(--demo-muted); line-height: 1.8; }
.picker-example__result { min-height: 24px; margin: 14px 0 0; color: var(--demo-muted); font-size: 13px; overflow-wrap: anywhere; }
.picker-actions { display: flex; justify-content: flex-end; }
@media (max-width: 640px) {
  .category-picker-preview { padding: 14px; }
  .picker-example { padding: 18px; }
  .picker-example__heading { display: block; }
  .picker-example__heading code { display: inline-block; margin-top: 8px; }
}
</style>
